 x=json.loads(p.read_text());x=x.get('structuredContent') or (json.loads(x['content'][0]['text']) if x['content'][0]['text'].lstrip().startswith('{') else {'error':x['content'][0]['text']});x=x.get('data',x);h=x.get('html','');t=Text();t.feed(h or '');s=' '.join(' '.join(t.parts).split());s=re.sub(r'[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}','[contact redacted]',s);s=re.sub(r'(?<![\w])(?:\+?1[ .-]?)?\(?[2-9]\d{2}\)?[ .-]\d{3}[ .-]\d{4}(?!\d)','[phone redacted]',s)
